// Кейс: .qa/tests/monitoring/MON-036.md (шаги 3–4, пассивная часть) · план: .qa/e2e-app/specs/app.md (1.59)
// Pixel «בית»: блок «ניטורים אחרונים» есть; после ухода в фон и возврата без перезапуска список тот же (новых сеансов нет), без задвоенных строк. Ничего не запускает и не меняет.
import { assert, skip, sh, ANDROID_PACKAGE } from '../lib.mjs';

export const name = 'Android «בית»: «ניטורים אחרונים» после фона → возврата — список тот же, без дублей #7f31a2 @android @app @prod-safe';

const ROW = /\d{1,2}:\d{2}\s*·/; // «היום, 18:23 · 17 דק׳ · התרעה אחת» (Figma 06.1)
async function rows(app) {
  const out = [];
  for (const n of await app.dump()) for (const v of [n.text, n.desc]) if (v && ROW.test(v) && !out.includes(v.trim())) out.push(v.trim());
  return out;
}

export default async function (app) {
  await app.restart();
  await app.waitFor('בית', { timeout: 30000, what: 'главный экран «בית»' });
  await app.waitFor('ניטורים אחרונים', { timeout: 20000, what: 'блок «ניטורים אחרונים»' });
  const before = await rows(app);
  if (!before.length) skip('в «ניטורים אחרונים» нет ни одного сеанса — нечего сравнивать (аккаунт без истории)');

  await sh('input keyevent KEYCODE_HOME');
  await sh(`monkey -p ${ANDROID_PACKAGE} -c android.intent.category.LAUNCHER 1`);
  await app.waitFor('ניטורים אחרונים', { timeout: 20000, what: 'блок «ניטורים אחרונים» после возврата из фона' });
  const after = await rows(app);

  assert(after[0] === before[0], `верхняя строка не изменилась после фона/возврата («${before[0]}» → «${after[0]}»; если за это время закончился сеанс на другом телефоне — перезапустить тест)`);
  const top = after.slice(0, 5);
  assert(new Set(top).size === top.length, `в первых строках нет задвоенных: ${top.join(' | ')}`);
}
